  (1 <= n <= 2^31)%Z -> from_primary n = false -> (AB mod 4096 = 0)%Z ->
  ((0 <= AB - 4096 /\ AB + sec_ru n <= kLowMemEnd + 1) \/ (kHighShadowEnd < AB - 4096 /\ AB + sec_ru n <= kHighMemEnd + 1))%Z ->
  rw_cells asegs m (g_instance + 0x40) [C8 (Z_to_bv 64 4096)] ->
  rw_cells asegs m (AB - 4096 + 16) [C8 (Z_to_bv 64 (needed2 n))] ->
  rw_cells asegs m (shad AB) [CB (Z.to_nat (rz_size n / 8)) sj1] ->
  rw_cells asegs m (shad (sec_tb n AB)) [CB (Z.to_nat ((AB + sec_ru n - sec_tb n AB) / 8)) sj2] ->
  ps_cells m ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 64)%Z -> (kHighShadowEnd + 8 <= lo)%Z ->
  mem_inv asegs m ->
  evt asegs (allocate_p2_exit sp gp tp F fc n AB B T (Z_to_bv 64 (sec_ru n)) s3v (Z_to_bv 64 (AB + rz_size n + n + 7)) m
               [(shad AB, shad AB + rz_size n / 8); (shad (sec_tb n AB), shad (sec_tb n AB) + (AB + sec_ru n - sec_tb n AB) / 8);
                (bv_unsigned sp - 64, bv_unsigned sp)]%Z lo
               (fun m' => rw_cells asegs m' (shad AB) [CB (Z.to_nat (rz_size n / 8)) (repeat (Z_to_bv 8 250) (Z.to_nat (rz_size n / 8)))]
                          /\ rw_cells asegs m' (shad (sec_tb n AB))
                               [CB (Z.to_nat ((AB + sec_ru n - sec_tb n AB) / 8))
                                   (repeat (Z_to_bv 8 250) (Z.to_nat ((AB + sec_ru n - sec_tb n AB) / 8)))]))
    (MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 0) (Z_to_bv 64 n) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 AB) s3v (Z_to_bv 64 (AB + rz_size n)) (Z_to_bv 64 (AB + rz_size n + -16))
             (Z_to_bv 64 2364504) (Z_to_bv 64 B) (Z_to_bv 64 0) (Z_to_bv 64 (AB + rz_size n + n)) (Z_to_bv 64 T) (Z_to_bv 64 1)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0xa15c0) fc None m (seg_rom asegs)).
